SELECT CASE WHEN ts>='2026-10-07T14:43' THEN 'after_B_commit' WHEN ts>='2026-10-07T02:02' THEN 'after_A_commit' ELSE 'before_A' END p, event_type, COUNT(*) FROM strategy_events WHERE ts>='2026-10-06' AND event_type LIKE 'FAST_FOLLOW%' GROUP BY 1,2 UNION ALL SELECT CASE WHEN ts>='2026-10-07T14:43' THEN 'after_B_commit' WHEN ts>='2026-10-07T02:02' THEN 'after_A_commit' ELSE 'before_A' END p, event_type, COUNT(*) FROM order_events WHERE ts>='2026-10-06' AND (event_type LIKE '%FAST_FOLLOW%') GROUP BY 1,2;
